1	<?php
2	
3	namespace common\models;
4	
5	use Yii;
6	use yii\behaviors\TimestampBehavior;
7	use common\components\Logger;
8	use yii\helpers\Url;
9	use common\modules\freespin\interfaces\FreespinProviderInterface;
10	use common\modules\freespin\services\DbFreespinProvidersGateway;
11	use common\modules\freespin\services\FreespinProviderFactory;
12	use common\modules\freespin\services\FreespinProvidersForCurrency;
13	use common\modules\freespin\services\FreespinQuotaPolicy;
14	
15	/**
16	 * This is the model class for table "freespin".
17	 *
18	 * @property int $id
19	 * @property string $player_id
20	 * @property string $currency
21	 * @property int|null $quantity
22	 * @property int|null $quantity_left
23	 * @property int|null $valid_from
24	 * @property int|null $valid_until
25	 * @property int|null $bet_id
26	 * @property int|null $total_bet_id
27	 * @property float|null $denomination
28	 * @property string|null $game_uuid
29	 * @property int|null $is_canceled
30	 * @property int|null $status
31	 * @property float|null $total_win
32	 * @property int|null $bonus_id
33	 * @property string|null $destination_event
34	 * @property int|null $created_at
35	 * @property int|null $updated_at
36	 * @property string $freespin_id
37	 * @property int|null $bonus_type
38	 * @property int|null $bonus_cod_id
39	 * @property int|null $campaign_id EGT Gift Spin campaign id (numeric); null для Gaminator
40	 *
41	 * @property MaxWinUserBonus $maxWinUserBonus
42	 * @property UserBonus $userBonus
43	 * @property array $statuses
44	 * @property Game $game
45	 * @property BonusCodLog $bonusCodLog
46	 * @property User $user
47	 * @property BonusCodLog $userBonusCod
48	 * @property Bonus $bonus
49	 * @property BonusCod $bonusCod
50	 * @property float|null $maxWinLeftUntilMaxAmount
51	 */
52	class Freespin extends \yii\db\ActiveRecord
53	{
54	    const STATUS_NEW = 1;//создана, но нужны доп параметры
55	    const STATUS_READY = 2;//готов к игре
56	    const STATUS_USED = 3;//идет игра
57	    const STATUS_END = 4;//фриспины закончены
58	    const STATUS_ERROR = 5;//ошибка
59	    const STATUS_CANCEL_ADMIN = 6;//отменен админом або автоматом по крону
60	    const STATUS_CANCEL_USER= 7;//отменен гравцем
61	    const STATUS_CANCEL_AUTO = 8;// відмінено автоматично при створенні ФС
62	    const BONUS = 1;
63	    const BONUS_COD = 2;
64	
65	    const EVENT_TOURNAMENT_WIN = 'tournament_win';
66	
67	    /**
68	     * {@inheritdoc}
69	     */
70	    public static function tableName()
71	    {
72	        return 'freespin';
73	    }
74	
75	    public function behaviors()
76	    {
77	        return [TimestampBehavior::class];
78	    }
79	
80	    /**
81	     * {@inheritdoc}
82	     */
83	    public function rules()
84	    {
85	        return [
86	            [['player_id', 'currency'], 'required'],
87	            [['quantity', 'quantity_left', 'valid_from', 'valid_until', 'bet_id', 'total_bet_id', 'is_canceled', 'status', 'created_at', 'updated_at','bonus_id','bonus_type','campaign_id'], 'integer'],
88	            [['denomination','total_win'], 'number'],
89	            [['freespin_id'], 'string'],
90	            [['currency'], 'string', 'max' => 4],
91	            [['destination_event'], 'string', 'max' => 64],
92	            [['game_uuid','player_id'], 'string', 'max' => 255],
93	        ];
94	    }
95	
96	    /**
97	     * {@inheritdoc}
98	     */
99	    public function attributeLabels()
100	    {
101	        return [
102	            'id' => Yii::t('app', 'ID'),
103	            'player_id' => Yii::t('app', 'Player ID'),
104	            'currency' => Yii::t('app', 'сurrency'),
105	            'quantity' => Yii::t('app', 'quantity'),
106	            'quantity_left' => Yii::t('app', 'Left'),
107	            'valid_from' => Yii::t('app', 'active_from'),
108	            'valid_until' => Yii::t('app', 'active_to'),
109	            'bet_id' => Yii::t('app', 'Bet ID'),
110	            'total_bet_id' => Yii::t('app', 'Total Bet ID'),
111	            'denomination' => Yii::t('app', 'Denomination'),
112	            'game_uuid' => Yii::t('app', 'Game Uuid'),
113	            'is_canceled' => Yii::t('app', 'canceled'),
114	            'status' => Yii::t('app', 'Status'),
115	            'total_win' => Yii::t('app', 'Total Win'),
116	            'created_at' => Yii::t('app', 'created_at'),
117	            'updated_at' => Yii::t('app', 'updated_at'),
118	            'freespin_id' => Yii::t('app', 'Freespin ID'),
119	            'destination_event' => Yii::t('app', 'Destination event'),
120	            'bonus_id' => Yii::t('app', 'bonus'),
121	        ];
122	    }
123	
124	    /**
125	     * @go-parity internal/models/user_bonus.go FindUserBonusByFreespinIDForUpdate
126	     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
127	     */
128	    public function getUserBonus()
129	    {
130	        return $this->hasOne(UserBonus::class, ['freespin_id' => 'freespin_id']);
131	    }
132	
133	
134	    /**
135	     * Создание freespin
136	     * @param $userUuid
137	     * @param $currency
138	     * @param $gameUid
139	     * @param $denomination
140	     * @param $bet
141	     * @param int $quantity
142	     * @param false $event
143	     * @return false|string(freespin_id)
144	     */
145	    public static function createFreeSpin($userUuid, $currency, $gameUid, $denomination, $bet, $quantity = 10,
146	                                          $bonusId = null, $event = false, $bonus_type = self::BONUS)
147	    {
148	
149	        // Labels будуються ДО ранніх виходів свідомо: саме на них раніше й губився контекст —
150	        // причина відмови писалась лише в info без bonus_id, і по логу неможливо було звести
151	        // «ФС не створились» до конкретного бонуса й гравця. А причина відмови майже завжди
152	        // у налаштуваннях саме бонуса: не та гра, не та валюта, вичерпаний ліміт.
153	        $logLabels = [
154	            'module' => 'freespin',
155	            'player_id' => $userUuid,
156	            'currency' => $currency,
157	            'game_uuid' => $gameUid,
158	            'bonus_id' => $bonusId,
159	            'bonus_type' => $bonus_type,
160	        ];
161	
162	        $gameModule = Yii::$app->getModule('game-search');
163	        $game = $gameModule->getGameBySlug(slug: $gameUid);
164	
165	        if(empty($game)){
166	            Logger::writeToLoki(
167	                'createFreeSpin: game not found for gameUid:' . $gameUid,
168	                'create_freespin',
169	                'error',
170	                $logLabels
171	            );
172	            Logger::writeError('createFreeSpin Game not found for gameUid:'.$gameUid
173	                . ' bonusId:' . var_export($bonusId, true) . ' userUuid:' . $userUuid);
174	            return false;
175	        }
176	
177	        // квота: Gaminator — будь-який ліміт у валюті (як було), AggregatorUA — ліміт ключа гри, EGT — без квоти
178	        // @infection-ignore-all тонкий адаптер: правило в FreespinQuotaPolicy::allows (тести AU-007), тут ранній вихід і логи, перевірка на стенді
179	        if (!self::quotaAllows($game, $currency)) {
180	            Logger::writeToLoki(
181	                'createFreeSpin: empty freespin limit for currency ' . $currency,
182	                'create_freespin',
183	                'error',
184	                $logLabels
185	            );
186	            Logger::writeError('createFreeSpin empty limit freespin for ' . $currency
187	                . ' bonusId:' . var_export($bonusId, true) . ' userUuid:' . $userUuid);
188	            return false;
189	        }
190	
191	
192	        $model = new Freespin();
193	        $model->player_id = $userUuid;
194	        $model->currency = $currency;
195	        $model->denomination = $denomination;
196	        $model->quantity = $quantity;
197	        $model->game_uuid = $gameUid;
198	        $model->status = Freespin::STATUS_NEW;
199	        $model->bonus_id = $bonus_type == self::BONUS ? $bonusId : null;
200	        $model->bonus_type = $bonus_type;
201	        $model->bonus_cod_id = $bonus_type == self::BONUS_COD ? $bonusId: null;
202	
203	        if($event){
204	            $model->destination_event = $event;
205	        }
206	
207	        if(self::resolveProvider($game)->usesTotalBet()){
208	            $model->total_bet_id = $bet;
209	        }else{
210	            $model->bet_id = $bet;
211	        }
212	
213	
214	        $return = false;
215	        $freespin = null;
216	        try {
217	            // 1) Персистимо запис фриспіна зі status NEW.
218	            if (!$model->validate() || !$model->save()) {
219	                Logger::writeToLoki(
220	                    'createFreeSpin: validate/save failed; errors:'
221	                        . json_encode($model->getErrors(), JSON_UNESCAPED_UNICODE),
222	                    'create_freespin',
223	                    'error',
224	                    $logLabels
225	                );
226	                Logger::writeInfo('createFreeSpin validate/save failed; errors:'
227	                    . json_encode($model->getErrors(), JSON_UNESCAPED_UNICODE));
228	                return false;
229	            }
230	
231	            // freespin_id генерується дефолтом БД (uuid_generate_v4()) і не повертається у модель
232	            // після INSERT — перечитуємо рядок, щоб отримати його перед зовнішнім викликом.
233	            // Читаємо з MASTER: без транзакції звичайний SELECT міг би піти на slave-репліку,
234	            // яка ще не догнала свіжий INSERT → null і fatal на $freespin->freespin_id.
235	            $freespin = Yii::$app->db->useMaster(function () use ($model) {
236	                return Freespin::find()->where(['id' => $model->id])->one();
237	            });
238	            if ($freespin === null) {
239	                // Рядок щойно вставлено, але не знайдено навіть на master — аномалія БД.
240	                Logger::writeToLoki(
241	                    'createFreeSpin: freespin row not found after save id:' . $model->id,
242	                    'create_freespin',
243	                    'error',
244	                    $logLabels
245	                );
246	                Logger::writeInfo('createFreeSpin freespin row not found after save id:' . $model->id);
247	                return false;
248	            }
249	            $logLabels['freespin_id'] = $freespin->freespin_id;
250	
251	            // 2) Зовнішній HTTP-виклик до провайдера — поза транзакцією.
252	            //    setCamping() сам персистить підсумковий статус (READY на успіх, ERROR на невдачу).
253	            $campingStart = microtime(true);
254	            $campingResult = $freespin->setCamping();
255	            $campingDuration = round(microtime(true) - $campingStart, 4);
256	
257	            // @infection-ignore-all лише рівень запису в лог; setCamping() — HTTP до провайдера, юніт-тестом не піднімається
258	            Logger::writeToLoki(
259	                'createFreeSpin: setCamping finished freespin_id:' . $freespin->freespin_id
260	                    . '; result:' . ($campingResult ? 'ok' : 'fail')
261	                    . '; external_call_duration:' . $campingDuration . 's',
262	                'create_freespin',
263	                $campingResult ? 'info' : 'error',
264	                $logLabels
265	            );
266	            Logger::writeInfo('createFreeSpin setCamping finished freespin_id:' . $freespin->freespin_id
267	                . '; result:' . ($campingResult ? 'ok' : 'fail')
268	                . '; external_call_duration:' . $campingDuration . 's');
269	
270	            // Провайдер відмовив — це найчастіша причина, чому гравець бачить
271	            // «Помилка створення бонуса». У info/warning її не знайти, тому дублюємо
272	            // в error разом із бонусом і гравцем.
273	            // @infection-ignore-all лише запис у лог; setCamping() — HTTP до провайдера, юніт-тестом не піднімається
274	            if (!$campingResult) {
275	                Logger::writeError('createFreeSpin setCamping failed freespin_id:' . $freespin->freespin_id
276	                    . ' bonusId:' . var_export($bonusId, true)
277	                    . ' userUuid:' . $userUuid
278	                    . ' gameUid:' . $gameUid
279	                    . ' currency:' . $currency);
280	            }
281	
282	            $return = $campingResult ? $freespin->freespin_id : false;
283	        } catch (\Exception $ex) {
284	            $tttext = 'Error create Freespin game_uuid:' . $gameUid . ' Host: ' . gethostname() . ' Exception : ' . $ex->getMessage();
285	            Logger::writeInfo($tttext);
286	            Logger::writeToLoki($tttext, 'create_freespin', 'error', $logLabels);
287	
288	            // Recovery-логіка у catch має бути куленепробивною: refresh()/save() самі можуть
289	            // кинути виняток, і він вилетів би з методу замість return false.
290	            try {
291	                if ($freespin !== null) {
292	                    // setCamping() міг встигнути зберегти статус (READY/ERROR) до винятку.
293	                    // Перечитуємо актуальний статус з MASTER, щоб рішення спиралося на реальний
294	                    // стан у БД, а не на in-memory значення, і ми не перетерли коректний статус.
295	                    Yii::$app->db->useMaster(function () use ($freespin) {
296	                        $freespin->refresh();
297	                    });
298	
299	                    if ((int)$freespin->status === self::STATUS_NEW) {
300	                        // Запис лишився NEW: setCamping упав ще до фіксації статусу. При цьому HTTP
301	                        // міг дійти до провайдера й створити кампанію → потенційно осиротілий запис.
302	                        // Фіксуємо ERROR (щоб NEW не накопичувались) + окремий orphan_risk-маркер,
303	                        // за яким reconciliation-крон знайде запис і за потреби викличе
304	                        // freespinCancel($freespin->freespin_id) на боці провайдера.
305	                        $freespin->status = self::STATUS_ERROR;
