/**
 * @go-parity internal/models/user_bonus.go RealAmount
 *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
 */
public function getRealAmount(): float
{
    //check max_win
    $amount = (float)$this->amount;
    if (!$this->maxWin) return $amount;
    return min($amount, $this->maxWin);
}

/**
 * @go-parity internal/models/max_win_user_bonus.go (user_id з user_bonus)
 *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
 */
public function getUserId(): ?int
{
    return $this->user_id;
}

/**
 * @go-parity internal/models/bonus_prepare.go PrepareGiftUserBonus (max_win_user_bonus)
 *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
 */
public function setMaxWin(?float $amount): void
{
    if ($amount === null) {
        return;
    }

    if ($this->maxWinUserBonus === null) {
        MaxWinUserBonus::create(
            userId: $this->user_id,
            maxWin: $amount,
            gameId: $this->freespin?->game?->id,
            userBonusId: $this->id,
            freespinId: $this->freespin?->id,
            isActive: (int)$this->status === self::STATUS_ACTIVE,
        );
        $this->refresh();
        return;
    }
    $this->maxWinUserBonus->max_win = $amount;
    $this->maxWinUserBonus->left_until_max_amount = $amount;
    $this->maxWinUserBonus->save();
    // Этот кейс не должен существовать, мы задаем max_win при создании и больше не меняем.
    // Но на всякий случай не будем возвращать ошибку, чтобы не сломать остальной функционал
    Logger::writeError('ERROR: USER_BONUS_MAX_WIN, ' . json_encode($this->id));
    $this->refresh();
}

public function getMaxWin(): ?float
{
    return $this->maxWinUserBonus?->max_win;
}

/**
 * @go-parity internal/models/max_win_user_bonus.go FindMaxWinIDByUserBonusID
 *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
 */
public function getMaxWinUserBonus(): ActiveQuery
{
    return $this->hasOne(MaxWinUserBonus::class, ['user_bonus_id' => 'id']);
}

public function getMaxWinLeftUntilMaxAmount(bool $useCache = true): ?float
{
    return MaxWinUserBonus::getLeftUntilMaxAmount(
        userId: $this->user_id,
        userBonusId: $this->id,
        useCache: $useCache
    );
}

public function setMaxWinLeftUntilMaxAmount(float $value): void
{
    MaxWinUserBonus::setLeftUntilMaxAmount(
        userId: $this->user_id,
        value: $value,
        userBonusId: $this->id
    );
}


/**
 * @go-parity internal/models/max_win_user_bonus.go HasMaxWin
 *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
 */
public function hasMaxWin(): bool
{
    return MaxWinUserBonus::hasMaxWin(userId: $this->user_id, userBonusId: $this->id);
}

/**
 * Сколько игрок уже получил в счёт лимита Max Win (лимит - остаток).
 * Значение берём напрямую из записи max_win_user_bonus — в БД оно авторитетное
 * и корректно как для активного, так и для завершённого бонуса.
 * Возвращает null, если Max Win для этого бонуса не задавался.
 */
public function getMaxWinReceived(): ?float
{
    $maxWinUserBonus = $this->maxWinUserBonus;
    if ($maxWinUserBonus === null) {
        return null;
    }
    return max(0, (float)$maxWinUserBonus->max_win - (float)$maxWinUserBonus->left_until_max_amount);
}

