    public function actionActivateBonus()
    {
        if (!Yii::$app->request->isAjax) {
            throw new ForbiddenHttpException('Only for Ajax requests');
        }

        Yii::$app->response->format = \yii\web\Response::FORMAT_JSON;
        if(Yii::$app->user->isBlockRequestForMe()){
            return [
                'success' => 0,
                'error' => Yii::t('app', 'time_interval')
            ];
        }
        Yii::$app->user->setBlockRequestForMe(3);

        $bonusId = (int) Yii::$app->request->post('bonusId');

        $user = Yii::$app->user->identity;
        /** @var UserBonus $userBonus */
        $userBonus = UserBonus::find()->where(['id'=>$bonusId,'user_id'=>$user->id])->one();
        if (empty($userBonus)) {
            $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'not_found')]);
            return ['success' => false, 'html' => $html];
        }

        if(!$userBonus->isActive()){
            $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'bonus_time_end')]);
            return ['success' => false, 'html' =>$html];
        }

        $wallet = Wallet::findOne([
            'user_id' => $user->id,
            'currency' => $userBonus->currency,
        ]);
        if (!($wallet)) {
            $wallet = new Wallet([
                'user_id' => $user->id,
                'currency' => $userBonus->currency,
                'active' => 1,
                'amount' => 0,
            ]);
            $wallet->save();
        }

        if (empty($wallet)) {
            $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'wallet_not_found')]);
            return ['success' => false, 'html' => $html];
        }
        if ($userBonus->is_promocod) {
            //якщо це промокод
            $bonusCod = $userBonus->bonusCod;
            if( !$bonusCod ){
                $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'not_found')]);
                return ['success' => false, 'html' =>$html];
            }
            if ($userBonus->status != UserBonus::STATUS_AVAILABLE) {
                $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'not_found')]);
                return ['success' => false, 'html' => $html];
            }

            //якщо це не вейджерний і промокод на депозит, то на баланс відразу
            if(!$userBonus->is_wager && $bonusCod->isForDeposit()){
                $transaction = Yii::$app->db->beginTransaction();
                try {
                    if ($userBonus->amount) {
                        if ($wallet->deposit($userBonus->getRealAmount()) && $userBonus->currency == Wallet::CURRENCY_CP) {
                            CpAccrualLog::writeLog($user->id, $userBonus->amount, CpAccrualLog::EVENT_BONUS);
                        }
                    }
                    $userBonus->accepted_time = time();
                    $userBonus->accrual_time = time();
                    $userBonus->status = UserBonus::STATUS_END;
                    $userBonus->save();
                    $transaction->commit();

