800	        $freespin = $this->findGiftSpin($data, $user, $wallet->currency);
801	        if (!$freespin) {
802	            return null; // anomalous GIFT_SPIN — let the normal win path credit + log
803	        }
804	
805	        // 1) progress (quantity_left / status / total_win), even for a losing spin
806	        FreespinProgressService::recordSpinProgress($freespin, $this->giftSpinRemaining($data), $amount);
807	
808	        // Close a linked bonus-code campaign when spins are exhausted — parity with
809	        // SiteController's sync `userBonusCod->closeBonus()` (the async pipeline only
810	        // flags BonusCodLog.used).
811	        $userBonusCod = $freespin->userBonusCod;
812	        if ($userBonusCod && (int)$freespin->quantity_left === 0) {
813	            $userBonusCod->closeBonus();
814	        }
815	
816	        // 2) credit routing — same predicate as SiteController's freespin-win branch.
817	        // The real/bonus split is computed by EgtWallet::giftSpinSplit and shared
818	        // with the idempotency replay so a retry reproduces the identical response.
819	        $creditRealSync = $this->giftSpinCreditsReal($freespin);
820	        $split = EgtWallet::giftSpinSplit($creditRealSync, $rawAmountCoins);
821	
822	        if ($creditRealSync && $amount > 0) {
823	            Yii::$app->db->createCommand(
824	                'UPDATE wallet SET amount = amount + :amount WHERE id = :id',
825	                [':amount' => $amount, ':id' => $wallet->id]
826	            )->execute();
827	            $wallet->amount = $wallet->amount + $amount;
828	        }
829	
830	        // 3) ledger record (idempotency key = transferId) tagged as a freespin win
831	        $game_action = [
832	            'player_id'          => $user->uid,
833	            'user_id'            => $user->id,
834	            'currency'           => $wallet->currency,
835	            'action'             => 'win',
836	            'amount'             => $amount,
837	            'transaction_id'     => $transferId,
838	            'bet_transaction_id' => $roundNumber,
839	            'game_uuid'          => $gameKey,
840	            'session_id'         => $sessionId,
841	            'type'               => 'freespin',
842	            'freespin_id'        => $freespin->freespin_id,
843	            'balance_before'     => $beforeAmount,
844	            'balance_after'      => $wallet->amount,
845	            'time'               => $time,
846	        ];
847	        GameTransaction::saveNewGameTransaction($game_action);
848	
849	        // 4) shared async pipeline: wager accrual / max-win capped deposit / bonus close
850	        //    (the same code path Gaminator freespin wins use)
851	        BackgroundGameProcess::runQueue($game_action, $user);
852	
853	        // Win not credited to the real account is reported to EGT as bonus money (§4.7).
854	        return $this->signedTransferResponse($wallet, $transferId, $split['real'], $split['bonus']);
855	    }
856	
857	    /**
858	     * Whether a gift-spin win is credited to the REAL balance synchronously (plain
859	     * freespin) vs routed to bonus money (wager / max-win) — the SiteController
860	     * freespin-win predicate. Deterministic from the freespin's bonus config, so
861	     * the idempotency replay reconstructs the same real/bonus split.
862	     */
863	    private function giftSpinCreditsReal(Freespin $freespin): bool
864	    {
865	        $userBonus = $freespin->userBonus;
866	        $hasMaxWin = ($userBonus && $userBonus->hasMaxWin()) || (!$userBonus && $freespin->hasMaxWin());
867	        $isWager   = $userBonus && $userBonus->is_wager;
868	
869	        return !($isWager || $hasMaxWin);
870	    }
871	
872	    /**
873	     * Reproduce the ORIGINAL deposit response for an idempotent retry (§4.7: the
874	     * operator must respond with the same response). A gift-spin win may have split
875	     * the amount into real/bonus (wager / max-win), so the replay reconstructs that
876	     * same split from the freespin instead of blindly reporting the whole amount as
877	     * real. Non-gift-spin — and a gift-spin whose freespin is not found, which
878	     * originally fell through to a full real credit — replay the full realAmount.
879	     */
880	    private function replayDepositResponse(array $data, string $reason, User $user, Wallet $wallet, string $transferId, int $rawAmountCoins): array
881	    {
882	        if ($reason === 'GIFT_SPIN') {
