// Перевірка тут, а не у win: виграш заблокованому все одно треба зарахувати
if ($this->user->getIsBlocked()) {
    return Protocol::error(Protocol::INTERNAL_ERROR, 'Your account has been blocked');
}

$selfLimitation = $this->findSelfLimitation();
if ($this->isSelfExcluded($selfLimitation)) {
    return $this->selfExclusionError();
}
if ($this->gameAction['type'] === 'bet' && !$this->passesProfitLimit($selfLimitation)) {
    return $this->selfExclusionError();
}

if ($this->gameAction['type'] === 'freespin') {
    return $this->handleFreespinBet();
}

$maxId = GameTransaction::getMaxId();
$amount = $this->gameAction['amount'];

$outcome = Yii::$app->db->transaction(function () use ($maxId, $amount) {
    $balance = $this->lockWallet();
    $this->gameAction['balance_before'] = $balance;

    // Повтор уже проведеної ставки — успіх без повторного списання, навіть якщо грошей вже не вистачає
    if ($this->transactionExists($this->gameAction['transaction_id'])) {
        $this->gameAction['balance_after'] = $balance;

        return 'replay';
    }
    if ($this->findRefundOf($this->gameAction['transaction_id'], $maxId)) {
        return 'refunded';
    }
    if ($balance < $amount) {
        return 'no_funds';
    }

    $this->gameAction['balance_after'] = (float)Yii::$app->db->createCommand(
        'UPDATE wallet SET amount = amount - :amount, sum_bet = sum_bet + :amount WHERE id = :id RETURNING amount',
        [':amount' => $amount, ':id' => $this->wallet->id]

